279: function FormatIcon({ format }: { format: DeliverableItem['format'] }) {
280:   switch (format) {
281:     case 'xlsx':
282:     case 'csv':
283:       return <FileSpreadsheet size={15} strokeWidth={1.65} className="shrink-0 text-emerald-400" />;
284:     case 'image':
285:       return <ImageIcon size={15} strokeWidth={1.65} className="shrink-0 text-amber-400" />;
286:     case 'html':
287:       return <FileCode2 size={15} strokeWidth={1.65} className="shrink-0 text-sky-400" />;
288:     case 'pdf':
289:       return <FileText size={15} strokeWidth={1.65} className="shrink-0 text-rose-400" />;
290:     case 'docx':
291:       return <FileText size={15} strokeWidth={1.65} className="shrink-0 text-blue-400" />;
292:     default:
293:       return <FileText size={15} strokeWidth={1.65} className="shrink-0 text-[var(--text)]" />;
294:   }
295: }
